from pathlib import Path
import json,hashlib,shutil,datetime
P=Path(__file__).resolve().parent
D=Path(r'D:\Proyectos\airr-investigacion\2026-10-27_simplex1137-binding')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def put(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def inv(root):return {p.relative_to(root).as_posix():dict(bytes=p.stat().st_size,sha256=sha(p)) for p in sorted(root.rglob('*')) if p.is_file()}
val=read(P/'validation1137.json');b=read(P/'BINDING1137.json')
assert val['all_passed'] and val['actual_record_linkage_pass']
assert sha(P/'model-response.json')==val['model_response_raw_sha256']==b['model_response_raw_sha256']
assert not D.exists() and not (P/'MANIFEST1137.json').exists() and not (P/'CLOSURE1137.json').exists()
put('INCIDENTS1137.json',dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),new_scientific_review=False,incidents=[dict(id='S1',kind='initial read-only output truncation',description='Combined tool output truncated part of schema/metadata display; relevant response schema, generated UUIDs, normalizer and validator were recovered by bounded reads. No source file changed.'),dict(id='S2',kind='live metadata population',description='First read observed generated template without paper.pdf. During serialization the operator populated exact metadata/PDF; later snapshot may include further operator metadata updates. Both preserved snapshots and final validator retain actual IDs/hash. No repository mutation was performed by this binding task.')],scientific_incidents_retained_in=['source1128/INCIDENTS1128.json','BINDING1137.json','model-response.json'],original_review_not_reopened=True))
(P/'README1137.txt').write_text('1137 — SERIALIZACIÓN DEL MISMO JUICIO1128\n\nNo es nueva evaluación, nueva nota ni voto adicional. model-response.json contiene únicamente la respuesta científica ARR-ASSESS-1.0; carece de campos controlados por el operador.\n\nMillennium6.3, importancia6.5, técnica8.8 y cinco criterios4/5 permanecen sin cambios. La recomendación accept representa la recomendación científica original; no es aceptación editorial. model_id=unknown expresa identidad efectiva sin atestación. involved_in_manuscript declara participación y no independencia.\n\nBINDING1137.json explica cada mapeo, conserva fecha original, bases, objeciones, incidencias, contexto y hashes. assessed_at en la respuesta es fecha de serialización; prompt_version identifica solo el formato posterior. source1128 contiene copias byte-idénticas del informe/veredicto completos y evidencia clave. El dossier1128 íntegro permanece intacto en sus rutasC/D originales y sus325archivos fueron reverificados.\n\nvalidation1137.json valida el enlace con el expediente real ya poblado y el PDF exacto. La fixture local se distingue expresamente y no sustituye ese control. validate1137.py utiliza copias idénticas del validador oficial y no escribe en el repositorio; el UUID transitorio que genera su normalizador no se conserva ni se registra. No se ejecutaron comandos Git, publicación o mutadores del expediente.\n\nPara mostrar esta evaluación, conservar el informe íntegro y cada objeción además de la proyección. No presentarla como segunda voz.\n',encoding='utf-8')
for root in [Path(b['source_review']['C']),Path(b['source_review']['D'])]:assert inv(root)==b['source_review']['full_source_inventory']
payload=inv(P)
put('MANIFEST1137.json',dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),scope='Binding dossier payloads; excludes manifest and closure to avoid self-reference.',payload_count=len(payload),files=[dict(path=p,**row) for p,row in payload.items()],source_report_sha256=b['source_report_sha256'],source_verdict_sha256=b['source_verdict_sha256'],model_response_sha256=sha(P/'model-response.json')))
shutil.copytree(P,D)
assert inv(P)==inv(D)
put('CLOSURE1137.json',dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),terminal=True,operation='serialization_same1128_not_new_review_or_vote',C=str(P),D=str(D),payload_count=len(payload),total_files=len(payload)+2,C_D_byte_identical=True,model_response_sha256=sha(P/'model-response.json'),structured_response_sha256=val['model_response_structured_sha256'],binding_sha256=sha(P/'BINDING1137.json'),validation_sha256=sha(P/'validation1137.json'),manifest_sha256=sha(P/'MANIFEST1137.json'),source_report_sha256=b['source_report_sha256'],source_verdict_sha256=b['source_verdict_sha256'],original1128_325files_C_D_unchanged=True,actual_registry_link_validated=True,no_runtime_attestation=True,no_editorial_acceptance=True,no_publication=True))
shutil.copy2(P/'CLOSURE1137.json',D/'CLOSURE1137.json')
ci=inv(P);assert ci==inv(D) and len(ci)==len(payload)+2
assert {p:row for p,row in ci.items() if p not in ['MANIFEST1137.json','CLOSURE1137.json']}==payload
print(json.dumps(dict(terminal=True,files_C_D_identical=len(ci),model_response_sha256=sha(P/'model-response.json'),structured_response_sha256=val['model_response_structured_sha256'],binding_sha256=sha(P/'BINDING1137.json'),manifest_sha256=sha(P/'MANIFEST1137.json'),closure_sha256=sha(P/'CLOSURE1137.json'))))
